import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Operation and maintenance","description":"","frontmatter":{"order":5,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/02.anleitungen/05.betrieb-und-wartung.md"},"headers":[],"relativePath":"adapter/sourceanalytix/anleitungen/betrieb-und-wartung.md","filePath":"adapter/sourceanalytix/anleitungen/betrieb-und-wartung.md","lastUpdated":null}'),r={name:"adapter/sourceanalytix/anleitungen/betrieb-und-wartung.md"};function i(n,e,h,l,d,u){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="operation-and-maintenance" tabindex="-1">Operation and maintenance <a class="header-anchor" href="#operation-and-maintenance" aria-label="Permalink to &quot;Operation and maintenance&quot;">​</a></h1><p><a id="update-sourceanalytix-downgrade"></a></p><h2 id="how-do-i-update-sourceanalytix-and-what-is-a-downgrade" tabindex="-1">How do I update SourceAnalytix (and what is a downgrade)? <a class="header-anchor" href="#how-do-i-update-sourceanalytix-and-what-is-a-downgrade" aria-label="Permalink to &quot;How do I update SourceAnalytix (and what is a downgrade)?&quot;">​</a></h2><p><strong>In short:</strong> For now, SourceAnalytix is only distributed through the &quot;latest&quot; (beta) repository, not through &quot;stable&quot;. Admin therefore only shows an update if the &quot;latest&quot; repository is active in the ioBroker system settings. You then update like any other adapter on the &quot;Adapters&quot; tab. Your states and settings are kept.</p><p>SourceAnalytix is missing from the stable repository entirely (checked on 13 November 2026). That is not a problem with your installation. SourceAnalytix only moves to the stable repository after a test phase. After that, you also get updates with &quot;stable&quot;.</p><h3 id="how-to-update" tabindex="-1">How to update <a class="header-anchor" href="#how-to-update" aria-label="Permalink to &quot;How to update&quot;">​</a></h3><ol><li>Back up your ioBroker system.</li><li>In Admin, open the system settings and, in the &quot;Repositories&quot; section, select the &quot;latest&quot; (beta) repository as the active one.</li><li>Open the &quot;Adapters&quot; tab and refresh the adapter list.</li><li>Click the update button for SourceAnalytix.</li><li>Then check on the &quot;Instances&quot; tab that the instance is running, and check the log to see that it started without errors.</li></ol><p>From the console, use <code>iobroker upgrade sourceanalytix</code>. This also only works with a repository that contains SourceAnalytix, so today only with &quot;latest&quot;. You install a specific version with <code>iobroker upgrade sourceanalytix@0.6.1</code>. Write the version number without a leading &quot;v&quot;.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Since v0.6.0, SourceAnalytix needs Node.js 22, js-controller 6.0.11 and Admin 7.8.23 or newer. From v0.7.0, Admin 8.0.0 or newer is required, because the instance settings are built on it. If one of these requirements is older, ioBroker doesn&#39;t offer the update or the installation fails. See <a href="./../erste-schritte/installation#requirements-sourceanalytix-have-node-js">Requirements</a>.</p></div><h3 id="what-happens-to-your-data-during-an-update" tabindex="-1">What happens to your data during an update <a class="header-anchor" href="#what-happens-to-your-data-during-an-update" aria-label="Permalink to &quot;What happens to your data during an update&quot;">​</a></h3><p>All values are stored as states and objects in ioBroker. An update doesn&#39;t change them. When you update to v0.6.0 or newer, this also applies:</p><ul><li>The &quot;Technical ID&quot;, which is the folder name under <code>sourceanalytix.0</code>, stays the same. SourceAnalytix enters the previous ID as the output ID in the datapoint&#39;s settings.</li><li>The rounding that applied until now is saved once per datapoint. If the instance defaults change later, existing datapoints keep their rounding.</li><li>New states for prices and price history appear under <code>sourceanalytix.0.priceDefinitions</code>, <code>priceHistory</code> and <code>basicPriceHistory</code>.</li></ul><p><strong>From v0.7.0:</strong> After the update, all your existing sources are listed on the &quot;Overview&quot; tab of the instance settings, with their existing settings. You don&#39;t have to set anything up again. Then check the &quot;Problems&quot; tab once. It shows, for example, unsuitable start values or a missed period rollover, with a suggestion on how to fix it (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1269" target="_blank" rel="noreferrer">#1269</a>).</p><h3 id="i-don-t-see-an-update" tabindex="-1">I don&#39;t see an update <a class="header-anchor" href="#i-don-t-see-an-update" aria-label="Permalink to &quot;I don&#39;t see an update&quot;">​</a></h3><ul><li><strong>Wrong repository:</strong> If &quot;stable&quot; is active, SourceAnalytix doesn&#39;t show up there with a new version. Switch to &quot;latest&quot; as described above.</li><li><strong>Installed from GitHub:</strong> If you installed SourceAnalytix directly from GitHub via the cat icon, Admin shows no update for that installation. Install the version you want from the &quot;latest&quot; repository over it, and you get updates again.</li><li><strong>Requirements too old:</strong> See the note above.</li></ul><h3 id="what-do-versions-like-0-4-8-alpha-3-mean" tabindex="-1">What do versions like 0.4.8-alpha.3 mean? <a class="header-anchor" href="#what-do-versions-like-0-4-8-alpha-3-mean" aria-label="Permalink to &quot;What do versions like 0.4.8-alpha.3 mean?&quot;">​</a></h3><p>The part after the hyphen marks a pre-release for testing (<code>alpha</code>, <code>beta</code>). The version without a suffix is newer than any of its pre-releases: <code>0.4.8</code> is newer than <code>0.4.8-beta.0</code>. Only install a pre-release if the developer asks for testers, and back up first.</p><h3 id="downgrade-going-back-to-an-older-version" tabindex="-1">Downgrade: going back to an older version <a class="header-anchor" href="#downgrade-going-back-to-an-older-version" aria-label="Permalink to &quot;Downgrade: going back to an older version&quot;">​</a></h3><p>A downgrade installs an older version over the existing one. You only need it if a new version has a bug on your system.</p><ol><li>Make a backup.</li><li>Switch on expert mode on the &quot;Adapters&quot; tab.</li><li>For SourceAnalytix, choose &quot;Install a specific version&quot; and pick the version you want.</li><li>Alternatively, use the console, again with the &quot;latest&quot; repository active: <code>iobroker upgrade sourceanalytix@&lt;version&gt;</code>, for example <code>iobroker upgrade sourceanalytix@0.6.1</code>.</li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>An older version doesn&#39;t know settings that only a newer one introduced. If you go back below v0.6.0, for example, SourceAnalytix doesn&#39;t know custom output IDs. If you changed one, the older version writes the values under the old ID again. If in doubt, restore the backup instead of just switching versions.</p></div><p><strong>From v0.6.2:</strong> When you update to v0.6.2, old <code>valueAtDeviceInit</code> entries stay in the datapoint settings. SourceAnalytix no longer reads them, and you don&#39;t have to do anything (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1263" target="_blank" rel="noreferrer">#1263</a>).</p><p><strong>See also:</strong> <a href="./../erste-schritte/installation#install-sourceanalytix-create-instance">Installation and creating an instance</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#after-update-restore-values-0">Values are 0 after an update or restore</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#known-bugs-older-versions-please">Known bugs in older versions</a> · <a href="#data-back-up-move-new">Where is the data, how do I back it up and how do I move it?</a></p><p><a id="disable-datapoint-remove-sources-states"></a></p><h2 id="how-do-i-switch-off-a-datapoint-or-remove-sources-and-states" tabindex="-1">How do I switch off a datapoint or remove sources and states? <a class="header-anchor" href="#how-do-i-switch-off-a-datapoint-or-remove-sources-and-states" aria-label="Permalink to &quot;How do I switch off a datapoint or remove sources and states?&quot;">​</a></h2><p><strong>In short:</strong> From v0.7.0, open the source in the instance settings and choose one of two actions under &quot;Actions&quot;. &quot;Deactivate&quot; stops SourceAnalytix for this source. All values are kept, and you can activate it again at any time. &quot;Delete data&quot; removes the source&#39;s folder with all values and years, plus the SourceAnalytix settings on the datapoint, for good.</p><h3 id="deactivate-or-delete-data" tabindex="-1">Deactivate or delete data? <a class="header-anchor" href="#deactivate-or-delete-data" aria-label="Permalink to &quot;Deactivate or delete data?&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>&quot;Deactivate&quot;</th><th>&quot;Delete data&quot;</th></tr></thead><tbody><tr><td>SourceAnalytix keeps calculating</td><td>no</td><td>no</td></tr><tr><td>Folder <code>sourceanalytix.0.&lt;device&gt;</code> with all years</td><td>stays</td><td>is deleted</td></tr><tr><td>Settings on the datapoint (price, start values, offset)</td><td>stay</td><td>are deleted</td></tr><tr><td>Undo</td><td>with &quot;Activate&quot;</td><td>not possible</td></tr></tbody></table><h3 id="how-to-deactivate-a-source-from-v0-7-0" tabindex="-1">How to deactivate a source (from v0.7.0) <a class="header-anchor" href="#how-to-deactivate-a-source-from-v0-7-0" aria-label="Permalink to &quot;How to deactivate a source (from v0.7.0)&quot;">​</a></h3><ol><li>Under &quot;Instances&quot;, open the settings of the SourceAnalytix instance, then open the source on the &quot;Overview&quot; tab.</li><li>Under &quot;Actions&quot;, in the &quot;Deactivate&quot; row, click the &quot;Deactivate&quot; button. It applies immediately, without a restart.</li><li>In the overview, the source now has the status &quot;Deactivated&quot;. Its states stay in place but are no longer updated.</li></ol><p>You can switch the source back on in the same place with &quot;Activate&quot;. SourceAnalytix then carries on calculating with the stored settings.</p><h3 id="how-to-delete-the-data-of-a-source-from-v0-7-0" tabindex="-1">How to delete the data of a source (from v0.7.0) <a class="header-anchor" href="#how-to-delete-the-data-of-a-source-from-v0-7-0" aria-label="Permalink to &quot;How to delete the data of a source (from v0.7.0)&quot;">​</a></h3><ol><li>Open the source as above and, in the &quot;Delete data&quot; row, click &quot;Delete&quot;.</li><li>The dialog shows what will be removed: the number of datapoints in the folder, the archive of the years, the total and the SourceAnalytix settings on the datapoint.</li><li>To confirm, type the name of the source and click &quot;Delete for good&quot;.</li></ol><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>&quot;Delete data&quot; can&#39;t be undone. The total, start values and all years are gone afterwards. Make a backup first if you might still need the values, and use &quot;Deactivate&quot; if you only want to pause.</p></div><p>Both actions need a running instance. If it is stopped, the instant actions are disabled.</p><h3 id="switching-off-many-sources-at-once" tabindex="-1">Switching off many sources at once <a class="header-anchor" href="#switching-off-many-sources-at-once" aria-label="Permalink to &quot;Switching off many sources at once&quot;">​</a></h3><p>If you activated many datapoints by accident, it is quicker to switch them off on the &quot;Objects&quot; tab. Select the datapoints, open their shared settings with the wrench icon, and untick &quot;enabled&quot; under <code>sourceanalytix.0</code>. The source folders stay in place. You can then delete them one by one with &quot;Delete data&quot; or on the &quot;Objects&quot; tab.</p><p><strong>From v0.7.0:</strong> The custom settings dialog only has the &quot;enabled&quot; checkbox now. You can no longer change other settings there, such as the price definition or threshold, for several datapoints at once. You set them for each source in its detail view (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1286" target="_blank" rel="noreferrer">#1286</a>).</p><h3 id="datapoint-deleted" tabindex="-1">Datapoint deleted <a class="header-anchor" href="#datapoint-deleted" aria-label="Permalink to &quot;Datapoint deleted&quot;">​</a></h3><p>If you delete the source datapoint itself, for example because you removed a device, SourceAnalytix switches the source off on its own. The log says &quot;Source state … was deleted; SourceAnalytix disabled it while retaining calculated history&quot;. The calculated values are kept.</p><p><strong>From v0.7.0:</strong> The &quot;Problems&quot; tab reports such a source as &quot;Datapoint no longer exists&quot; and suggests &quot;Deactivate or delete the data&quot;. A folder that no longer has a datapoint appears in the overview as &quot;Folder without datapoint&quot; and can be removed there with &quot;Delete data&quot;. Transferring the data to a new datapoint is planned (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1271" target="_blank" rel="noreferrer">#1271</a>).</p><h3 id="removing-individual-periods" tabindex="-1">Removing individual periods <a class="header-anchor" href="#removing-individual-periods" aria-label="Permalink to &quot;Removing individual periods&quot;">​</a></h3><p>If you just don&#39;t want certain states any more, such as the quarters, switch the option off on the &quot;Main settings&quot; tab of the instance settings. SourceAnalytix deletes the matching states at the next start. States you delete by hand, however, it creates again as long as the option and the source are active.</p><p><strong>Up to v0.6.x:</strong> The only way to switch a source off was the &quot;enabled&quot; checkbox in the datapoint&#39;s SourceAnalytix settings (&quot;Objects&quot; tab, wrench icon). There was no action for deleting. You deleted the folder under <code>sourceanalytix.0</code> by hand on the &quot;Objects&quot; tab after switching the source off.</p><p><strong>See also:</strong> <a href="#restart-datapoint-clean-up-old">How do I start over with a datapoint and clean up old years?</a> · <a href="#data-back-up-move-new">Where is the data, how do I back it up and how do I move it?</a> · <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Where do I configure SourceAnalytix for a datapoint?</a></p><p><a id="data-back-up-move-new"></a></p><h2 id="where-is-the-data-how-do-i-back-it-up-and-how-do-i-move-it" tabindex="-1">Where is the data, how do I back it up and how do I move it? <a class="header-anchor" href="#where-is-the-data-how-do-i-back-it-up-and-how-do-i-move-it" aria-label="Permalink to &quot;Where is the data, how do I back it up and how do I move it?&quot;">​</a></h2><p><strong>In short:</strong> SourceAnalytix has no database of its own. All values are stored as normal objects and states in ioBroker, and each source&#39;s settings are in its datapoint&#39;s object. A full ioBroker backup, for example with BackItUp, therefore contains everything. To move to new hardware, restore this backup on the new system, but not shortly before midnight.</p><h3 id="where-everything-is" tabindex="-1">Where everything is <a class="header-anchor" href="#where-everything-is" aria-label="Permalink to &quot;Where everything is&quot;">​</a></h3><table tabindex="0"><thead><tr><th>What</th><th>Where</th></tr></thead><tbody><tr><td>Total, running periods, previous periods, yearly archive</td><td>Folder <code>sourceanalytix.0.&lt;device&gt;</code></td></tr><tr><td>Last processed periods and cost memory</td><td><code>periodMemory</code> and <code>dynamicCostMemory</code> in the same folder</td></tr><tr><td>Source settings with start values and offset</td><td>In the object of the source datapoint under <code>common.custom.sourceanalytix.0</code></td></tr><tr><td>Price definitions and instance options</td><td>In the instance settings (object <code>system.adapter.sourceanalytix.0</code>)</td></tr><tr><td>Prices and price history</td><td><code>sourceanalytix.0.priceDefinitions</code>, <code>sourceanalytix.0.priceHistory</code> and <code>sourceanalytix.0.basicPriceHistory</code></td></tr><tr><td>Recorded history</td><td>In your history adapter, not in SourceAnalytix</td></tr></tbody></table><p>From v0.7.0, you find the Technical ID in the source detail under &quot;For experts&quot;.</p><h3 id="what-belongs-in-the-backup" tabindex="-1">What belongs in the backup <a class="header-anchor" href="#what-belongs-in-the-backup" aria-label="Permalink to &quot;What belongs in the backup&quot;">​</a></h3><p>Always back up the whole ioBroker system with objects and states. A backup of just the <code>sourceanalytix.0</code> folder is not enough, because the start values and offset are stored on the source datapoint. Without them, the total no longer matches the meter after a restore. If ioBroker runs with Redis, include the Redis backup too.</p><h3 id="how-to-move-to-new-hardware" tabindex="-1">How to move to new hardware <a class="header-anchor" href="#how-to-move-to-new-hardware" aria-label="Permalink to &quot;How to move to new hardware&quot;">​</a></h3><ol><li>Don&#39;t plan the move shortly before midnight, so that no period rollover falls into the time when no system is running.</li><li>Make a full backup on the old system.</li><li>Install ioBroker and SourceAnalytix on the new system (see <a href="./../erste-schritte/installation#install-sourceanalytix-create-instance">Installation</a>) and restore the backup.</li><li>Start the instance. If it missed a day, week or month rollover, it catches up once per source at startup.</li><li>On the &quot;Problems&quot; tab of the instance settings, check that there are no findings, and compare the total with your meter (from v0.7.0).</li></ol><p>If the total differs from the meter, align it with the action &quot;Align meter reading&quot;, see <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correcting wrong values</a>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Exporting just the object tree gives you the structure but no values. Creating the same sources on the new system doesn&#39;t replace the restore either: SourceAnalytix then starts with new start values.</p></div><p>If the source datapoint gets a different ID on the new system, for example because you connect the devices with a different adapter, SourceAnalytix treats it as a new source with a new folder. The old folder stays as an archive. Transferring the data to a new datapoint is planned (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1271" target="_blank" rel="noreferrer">#1271</a>).</p><p><strong>From v0.6.2:</strong> SourceAnalytix splits the consumption between the last value before midnight and the first one after it between the old and the new day, in proportion to time (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1260" target="_blank" rel="noreferrer">#1260</a>). So even if the move does span midnight, not everything ends up on the new day.</p><p><strong>See also:</strong> <a href="#iobroker-was-down-midnight-recover">ioBroker was off at midnight</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#after-update-restore-values-0">Values are 0 after an update or restore</a> · <a href="#update-sourceanalytix-downgrade">How do I update SourceAnalytix (and what is a downgrade)?</a></p><p><a id="restart-datapoint-clean-up-old"></a></p><h2 id="how-do-i-start-over-with-a-datapoint-and-clean-up-old-years" tabindex="-1">How do I start over with a datapoint and clean up old years? <a class="header-anchor" href="#how-do-i-start-over-with-a-datapoint-and-clean-up-old-years" aria-label="Permalink to &quot;How do I start over with a datapoint and clean up old years?&quot;">​</a></h2><p><strong>In short:</strong> From v0.7.0, you delete the source&#39;s data with the action &quot;Delete data&quot; and set it up again with &quot;Add source&quot;. SourceAnalytix then treats it like a first activation and starts all periods at 0. You can safely delete the folders of finished years on the &quot;Objects&quot; tab, independently of this.</p><p>Deleting just the source&#39;s folder is not enough for a fresh start. The start values and offset are stored in the settings on the datapoint, and as long as the source is active, SourceAnalytix creates the folder again at the next start with these values. &quot;Delete data&quot; therefore removes both.</p><h3 id="how-to-start-over-from-v0-7-0" tabindex="-1">How to start over (from v0.7.0) <a class="header-anchor" href="#how-to-start-over-from-v0-7-0" aria-label="Permalink to &quot;How to start over (from v0.7.0)&quot;">​</a></h3><ol><li>Under &quot;Instances&quot;, open the settings of the SourceAnalytix instance, then open the source on the &quot;Overview&quot; tab.</li><li>Under &quot;Actions&quot;, choose &quot;Delete data&quot;, type the name of the source and click &quot;Delete for good&quot;. The folder and the settings on the datapoint are then gone.</li><li>On the &quot;Overview&quot; tab, click &quot;Add source&quot; and select the same datapoint.</li><li>In the &quot;Start values&quot; step, choose &quot;Count from now&quot;. All periods then start at 0.</li><li>With the first value, the log says &quot;Initiating … for the first time in SourceAnalytix&quot; and &quot;Initialized empty period start values for … from current reading …&quot;.</li></ol><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>&quot;Delete data&quot; also removes the previous total. If you only want to repair wrong numbers, use &quot;Align meter reading&quot; instead, see <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correcting wrong values</a>. More about the two actions &quot;Deactivate&quot; and &quot;Delete data&quot; is under <a href="#disable-datapoint-remove-sources-states">Switching off a datapoint or removing sources</a>.</p></div><h3 id="cleaning-up-old-years" tabindex="-1">Cleaning up old years <a class="header-anchor" href="#cleaning-up-old-years" aria-label="Permalink to &quot;Cleaning up old years&quot;">​</a></h3><p>Every year with &quot;Year statistics&quot; switched on gets its own folder <code>sourceanalytix.0.&lt;device&gt;.&lt;year&gt;</code>. Folders of finished years are pure history and can be deleted.</p><ol><li>In Admin, open the &quot;Objects&quot; tab and then <code>sourceanalytix.0.&lt;device&gt;</code>.</li><li>Delete the folder of the year you no longer need, for example <code>2023</code>.</li><li>Don&#39;t delete <code>currentYear</code>, <code>cumulativeReading</code> or <code>periodMemory</code>, and don&#39;t delete the folder of the current year. SourceAnalytix still needs these states. As long as the source is active, it creates them again at the next start anyway.</li></ol><p>The action &quot;Recalculate costs from date&quot; only recalculates periods whose states still exist. It skips deleted years.</p><p>If you don&#39;t want any more weekly or yearly folders in the future, switch off the options &quot;Weeks&quot;, &quot;Months&quot; and &quot;Quarters&quot; under &quot;Year statistics&quot; on the &quot;Main settings&quot; tab of the instance settings. SourceAnalytix then deletes the states in the current year&#39;s folder and leaves older years alone.</p><p><strong>Up to v0.6.x:</strong> There was no action for deleting. To start over, you had to switch the source off, delete its folder on the &quot;Objects&quot; tab and also remove the stored start values and the offset on the datapoint. Otherwise the new activation didn&#39;t count as the first one. From v0.7.0, &quot;Delete data&quot; does all this in one step.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">What do I enter for the start values (and in which unit)?</a> · <a href="#data-back-up-move-new">Where is the data, how do I back it up and how do I move it?</a> · <a href="./werte-auswerten#evaluate-across-years-adjusting-everything">Evaluating across several years</a></p><p><a id="iobroker-was-down-midnight-recover"></a></p><h2 id="iobroker-was-off-at-midnight-how-do-i-catch-up-the-day-rollover" tabindex="-1">ioBroker was off at midnight: how do I catch up the day rollover? <a class="header-anchor" href="#iobroker-was-off-at-midnight-how-do-i-catch-up-the-day-rollover" aria-label="Permalink to &quot;ioBroker was off at midnight: how do I catch up the day rollover?&quot;">​</a></h2><p><strong>In short:</strong> Usually you don&#39;t have to do anything. For each source, SourceAnalytix remembers which day, week and month it last closed, and catches up on missed rollovers itself at the next start. If the instance keeps running, it also checks every hour whether a rollover is missing. From v0.7.0, you can also trigger the rollover in the instance settings with the action &quot;Recover periods&quot;.</p><h3 id="what-sourceanalytix-catches-up-on-its-own" tabindex="-1">What SourceAnalytix catches up on its own <a class="header-anchor" href="#what-sourceanalytix-catches-up-on-its-own" aria-label="Permalink to &quot;What SourceAnalytix catches up on its own&quot;">​</a></h3><ul><li><strong>At startup:</strong> At startup, each source compares the stored status in the state <code>sourceanalytix.0.&lt;device&gt;.periodMemory</code> with today&#39;s date. If a day, week, month, quarter or year rollover is missing, it processes it once. The log then says &quot;Processing calendar rollover for …&quot;.</li><li><strong>Every hour:</strong> A safety check catches up on a rollover that the midnight schedule missed even though the instance was running, for example after the computer woke from sleep or the system time was corrected.</li></ul><p>When catching up, the previous periods such as <code>01_previousDay</code> also get the time stamp 23:59:59 of the previous day. If the outage lasted several days, SourceAnalytix still only processes one rollover. <code>01_previousDay</code> then contains the consumption of the last day before the outage, and the days in between don&#39;t get a value of their own.</p><h3 id="how-to-catch-up-the-rollover-by-hand-from-v0-7-0" tabindex="-1">How to catch up the rollover by hand (from v0.7.0) <a class="header-anchor" href="#how-to-catch-up-the-rollover-by-hand-from-v0-7-0" aria-label="Permalink to &quot;How to catch up the rollover by hand (from v0.7.0)&quot;">​</a></h3><ol><li>Under &quot;Instances&quot;, open the settings of the SourceAnalytix instance. If a rollover is missing, the &quot;Problems&quot; tab reports &quot;Period rollover missed&quot; for the affected source, with the button &quot;Recover&quot;.</li><li>Alternatively, open a source on the &quot;Overview&quot; tab and, under &quot;Actions&quot;, in the &quot;Recover periods&quot; row, click &quot;Recover&quot;.</li><li>&quot;Period rollover recovered for <source>&quot; then appears. Both ways only apply to this one source, the other sources are not touched. If no rollover is missing, nothing changes.</li></ol><h3 id="from-a-script-or-a-button-in-vis" tabindex="-1">From a script or a button in VIS <a class="header-anchor" href="#from-a-script-or-a-button-in-vis" aria-label="Permalink to &quot;From a script or a button in VIS&quot;">​</a></h3><p>Without the instance settings, use the state <code>sourceanalytix.0.info.recoverPeriods</code>: write <code>true</code> to it (unacknowledged, so <code>ack=false</code>). SourceAnalytix then catches up missed rollovers of <strong>all</strong> sources and resets the state to <code>false</code>. From a script, use <code>sendTo</code>, either for all sources or with <code>source</code> for just one. The response gives the number of sources:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// all sources</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sourceanalytix.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;recoverPeriods&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {}, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`Rollover recovered for \${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">recovered</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">} sources\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// one source only (from v0.7.0), ID of the source datapoint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sourceanalytix.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;recoverPeriods&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {source: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;shelly.0.SHEM-3#1#.Total.ConsumedPower&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (result.error) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result.message, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;warn&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>If the source is not active, the response is <code>{error: &#39;sourceNotActive&#39;}</code>.</p><p>If a rollover is already running, the call is skipped and the response is 0.</p><h3 id="where-the-consumption-during-the-outage-is-booked" tabindex="-1">Where the consumption during the outage is booked <a class="header-anchor" href="#where-the-consumption-during-the-outage-is-booked" aria-label="Permalink to &quot;Where the consumption during the outage is booked&quot;">​</a></h3><p><strong>From v0.6.2:</strong> For meter readings, SourceAnalytix splits the consumption between the last value before midnight and the first value after it in proportion to time. The share that falls into the old day goes to yesterday, the rest to the new day. Up to v0.6.1, everything landed on the new day (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1260" target="_blank" rel="noreferrer">#1260</a>).</p><p>An example: the last value arrives at 22:00, the next one after the restart at 2:00, and the meter counted 4 kWh in between. SourceAnalytix then books 2 kWh to yesterday and 2 kWh to today.</p><p>This doesn&#39;t apply to power sources (W). From v0.6.2, SourceAnalytix books their energy up to midnight to the old day itself at the rollover, but only if the instance was running at midnight (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1254" target="_blank" rel="noreferrer">#1254</a>).</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The rollover follows the clock of the computer or container that ioBroker runs on. If the time zone is wrong there, SourceAnalytix rolls over at the wrong hour. See <a href="./../fehlerbehebung/log-meldungen#midnight-crash-rollover-wrong-time">Crash or rollover at the wrong time</a>.</p></div><p><strong>See also:</strong> <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Where do I find yesterday, last week, last month (previous states)?</a> · <a href="./../hintergrund/perioden-und-zeit#values-updated-live-midnight">When are values updated: live or at midnight?</a> · <a href="#data-back-up-move-new">Where is the data, how do I back it up and how do I move it?</a></p>`,93)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
